<script setup>
  const props = defineProps(['dId', 'dKey', 'width', 'height', 'quality', 'format', 'fit', 'transforms'])
  const { width, height, quality, format, fit, transforms } = props;

  const params = computed(() => {
    const o = {};
    if ( width ) o.width = width;
    if ( height ) o.height = height;
    if ( quality ) o.quality = quality;
    if ( format ) o.format = format;
    if ( fit ) o.fit = fit;
    if ( transforms ) o.transforms = transforms;
    return new URLSearchParams(o).toString()
  });

  const url = computed(() => {
    return `/api/photos/${props.dKey || props.dId}?type=${props.dKey ? 'key' : 'id'}&${params.value}`
  })

  const { pending, data } = useFetch(url.value);

  const pendingImageType = "image/png";
  const pendingImage = "";
</script>

<template>
  <img v-if="!pending && data" :src='`data:${data.type};base64,${data.image}`' />
  <img v-else :src='`data:${pendingImageType};base64,${pendingImage}`' />
</template>